import{_ as i,C as e,o as n,c as s,E as a,a2 as l}from"./chunks/framework.uPk2SrVb.js";const m=JSON.parse('{"title":"审批已经用掉，事情究竟办成了吗？","description":"","frontmatter":{"title":"审批已经用掉，事情究竟办成了吗？","date":"2026-10-29","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"一次性审批凭据被消费，是否就能证明批准的业务效果已经成功交付？","summary":"固定方法的隔离探针中，成功、效果前失败和效果后异常共享同一个已消费状态，却产生不同效果。防重放与交付证据需要分别建模。","sources":["https://arxiv.org/html/2610.21063v1","https://microsoft.github.io/agent-governance-toolkit/adr/0030-action-bound-approval-protocol/"],"pageClass":"runtime-v6-article","item_id":"SIG-20261029-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-29-sig-20261029-003-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-10-29-sig-20261029-003.md","filePath":"zh/industry/2026-10-29-sig-20261029-003.md","lastUpdated":null}'),d={name:"zh/industry/2026-10-29-sig-20261029-003.md"};function p(c,t,h,u,b,g){const r=e("ArticleCover"),o=e("ArticleTableScroll");return n(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-10-29-sig-20261029-003-cover.png",kicker:"研究成果",title:"审批已经用掉，事情究竟办成了吗？",summary:"固定方法的隔离探针中，成功、效果前失败和效果后异常共享同一个已消费状态，却产生不同效果。防重放与交付证据需要分别建模。",version:"2026-10-29",languageHref:"/en/industry/2026-10-29-sig-20261029-003",languageLabel:"English"}),a(o,{language:"zh"}),t[0]||(t[0]=l('<h1 id="审批已经用掉-事情究竟办成了吗" tabindex="-1">审批已经用掉，事情究竟办成了吗？ <a class="header-anchor" href="#审批已经用掉-事情究竟办成了吗" aria-label="Permalink to &quot;审批已经用掉，事情究竟办成了吗？&quot;">​</a></h1><p>一项审批已经用掉，原审批的重试也被拒绝，但业务效果可能根本没有发生，也可能发生后没有留下成功记录。对批准智能体执行外部操作的系统来说，这两个结果需要完全不同的后续处置，不能都压成“审批已消费”。</p><p>同日研究对象的隔离探针把这一区别落到了具体执行顺序：<strong>审批只用一次，与业务效果成功交付，是不同的保证。</strong> 读者需要检查的不是有没有一个批准按钮，而是批准身份、消费状态、交付事实与恢复授权分别由什么证据承担。</p><h2 id="一个消费状态-三种执行结果" tabindex="-1">一个消费状态，三种执行结果 <a class="header-anchor" href="#一个消费状态-三种执行结果" aria-label="Permalink to &quot;一个消费状态，三种执行结果&quot;">​</a></h2><p>ASU（智能体操作加强认证方案）的固定执行方法，在核验审批后消费一次性批准，再调用执行器，正常返回后记录效果。本次内部实验沿用已完成的研究对象：直接运行抽取的方法与实际条件更新语句，使用内存数据库、合成效果描述、固定布尔回执判定替身和模拟执行器，不操作远程业务。<a href="https://github.com/Sports-Vision-Inc/agent-step-up/blob/056742b00a9d116a57525c75704820bb87756e84/asu/gateway.py" target="_blank" rel="noreferrer">固定网关源码</a></p><p>八个内部对照案例全部符合预期，其中三条执行路径最能说明问题。运行环境为 Python（编程语言）3.12.9 与 SQLite（嵌入式数据库）3.45.3。三条路径的审批均为“已消费”。下面“内存效果”是模拟执行器修改的计数，“成功记录”是正常返回后写入的实验记录，两者均不是远程服务的交付证明。</p><table tabindex="0"><thead><tr><th>合成执行器路径</th><th>首次响应 → 原审批重试</th><th>内存效果数 / 成功记录数</th></tr></thead><tbody><tr><td>正常返回</td><td>200 → 403</td><td>1 / 1</td></tr><tr><td>效果发生前抛出异常</td><td>500 → 403</td><td>0 / 0</td></tr><tr><td>内存效果发生后抛出异常，模拟确认丢失</td><td>500 → 403</td><td>1 / 0</td></tr></tbody></table><p>这三行显示：消费状态相同，效果与记录却不同。后两行的首次响应与重试响应也完全相同，调用者单靠这些信号无法区分“没做成”和“做了但确认丢失”。这是内部合成故障注入的结果，不是已观察到的生产事故。</p><p>另外五个对照分别覆盖工具改变、参数改变、无效回执、待批准状态及过期消费；它们均没有调用执行器。这说明探针同时保留了拒绝路径，不能把它描述成一个允许任意修改或重放的演示。</p><h2 id="关键间隙在消费与记账之间" tabindex="-1">关键间隙在消费与记账之间 <a class="header-anchor" href="#关键间隙在消费与记账之间" aria-label="Permalink to &quot;关键间隙在消费与记账之间&quot;">​</a></h2><p>已读取的实现检查会话与用户、审批终态、已存和重新提交的效果摘要，以及重新解析的原始参数。回执核验先于“已批准且未过期”的条件数据库更新，后续执行拿到存储中的效果描述。这里的摘要绑定回答的是“本次是否执行被批准的对象”。<a href="https://github.com/Sports-Vision-Inc/agent-step-up/tree/056742b00a9d116a57525c75704820bb87756e84/asu" target="_blank" rel="noreferrer">网关方法及消费实现</a></p><p>研究解释是，消费先提交、执行在后，而效果记录依赖正常返回，便形成了两个不同问题：该批准是否还能再次使用，外部效果是否已经成功。拒绝再次使用批准，对第一个问题有意义；它不能代替第二个问题的事实记录。调用失败也不自动意味着业务效果为零。</p><p>这不是建议简单地把消费移动到执行之后。提前消费可以优先防止重复调用；延后消费则需要重新回答并发与重试怎样避免重复效果。真实执行器可能已经提供幂等能力，即使用同一个防重复流水号重复提交只产生一次业务效果，或者允许按标识查询结果。本轮没有审计完整执行器，因此不声称每个部署都会丢失效果。</p><h2 id="协议要求与运行证据应分开" tabindex="-1">协议要求与运行证据应分开 <a class="header-anchor" href="#协议要求与运行证据应分开" aria-label="Permalink to &quot;协议要求与运行证据应分开&quot;">​</a></h2><p>Microsoft（微软）的智能体治理工具包中，ADR（架构决策记录）0030 所述的绑定动作审批协议，要求消费与执行事务或幂等边界共享，并要求执行时重新校验效果摘要、有效期、策略与审批链版本、认证后的批准者身份。个别允许票本身不能执行动作。<a href="https://microsoft.github.io/agent-governance-toolkit/adr/0030-action-bound-approval-protocol/" target="_blank" rel="noreferrer">该决策记录</a></p><p>这份来源来自另一组织，提供的是设计要求，不是对上述探针的独立复现，更不是已经测得的部署优越性。比较有用之处在于，它明确写出单用凭据以外还需要承担的事务或防重边界。协议要求存在，与某个运行系统实际完成该要求，是两类证据。</p><p>入口覆盖也不能从效果绑定中自动推出。OpenHands（开源智能体开发框架）的文档明确把直接工具调用的防护交给宿主调用方，而会话新动作路径才咨询确认策略。该同日研究对象只作为边界比较：批准约束必须经过相应路径才发挥作用。这不是漏洞指控，也不表示它接受了加强认证论文的审计。<a href="https://docs.openhands.dev/sdk/guides/security" target="_blank" rel="noreferrer">官方安全说明</a></p><h2 id="恢复时还缺哪项事实" tabindex="-1">恢复时还缺哪项事实 <a class="header-anchor" href="#恢复时还缺哪项事实" aria-label="Permalink to &quot;恢复时还缺哪项事实&quot;">​</a></h2><p>受治理执行至少应分清四件事：批准针对什么效果、凭据是否已消费、业务结果能否确认、谁有权启动恢复。前三者是不同对象的证据；最后一项涉及权限，不能从某个错误码中推导出来。</p><p>在效果后确认丢失的案例里，“再试一次”可能重复业务效果，“当作成功”又可能掩盖失败。本文没有实测通用恢复方案。研究对象支持的是一个待验证方向：把批准标识与执行器防重复流水号关联，保存可查询结果；当响应不明确时，明确谁可查询、补偿或请求重新批准。这些是后续验证问题，不是已经存在的能力。</p><h2 id="这次探针没有验证什么" tabindex="-1">这次探针没有验证什么 <a class="header-anchor" href="#这次探针没有验证什么" aria-label="Permalink to &quot;这次探针没有验证什么&quot;">​</a></h2><p>公开源码是作者项目的一手资料；八个案例属于本研究中心内部隔离实验，没有独立第三方复现。效果描述的摘要与规范化使用合成替身，回执核验使用固定布尔判定，因此本轮没有测试真实签名、人类知情同意、可信显示或凭据注册。内存异常也不能冒充完整的分布式崩溃实验。</p><p>固定读取修订是 056742b；论文作者的攻击矩阵记录另一棵带未提交改动的实验树。本文没有重建该实验树、重跑形式化证明或复现论文的大规模实验。论文与形式化结果仅作为作者提供的来源材料，发表、评审、引用和实现状态不意味着普遍有效性。</p><p>本次可以成立的结论停在证据边界：一次性审批消费可以约束凭据重用，但成功交付仍需另外证明。真正需要继续验证的是，结果不明确时能查到什么、谁可以采取动作，而不是把“已消费”改名为“已完成”。</p>',24))])}const f=i(d,[["render",p]]);export{m as __pageData,f as default};
